import { confirm, input, select, Separator } from '@inquirer/prompts'
import { logger } from '../../logger'
import type { Arguments } from './index'
import {
    Connector,
    type LazyCredential,
    ProjectFactory,
    ProjectInitValidation,
    type TemplateInfo,
    type Templates,
} from '@servicenow/sdk-api'

const appNamePrompt = async (defaultAppName: string = 'Now SDK Example App') => {
    function normalize(value: string) {
        return value.trim()
    }

    const raw = await input({
        message: 'Name of ServiceNow Application: ',
        default: defaultAppName,
        validate: (value) => ProjectInitValidation.validateAppName(normalize(value)) ?? true,
    })

    return normalize(raw)
}

const templatePrompt = async (templates: (TemplateInfo & { id: keyof Templates })[]) => {
    type Choice = { value: keyof Templates; name?: string; description?: string }
    const choices: (Separator | Choice)[] = []
    let lastCategory: string | undefined
    for (const template of templates) {
        if (template.category && lastCategory !== template.category) {
            choices.push(new Separator(`-- ${template.category} --`))
            lastCategory = template.category
        }
        choices.push({
            name: template.name,
            value: template.id,
            description: template.description,
        })
    }
    const raw = await select({
        message: 'Select a template:',
        pageSize: choices.length,
        choices,
    })
    return raw
}

const globalPrompt = async () => {
    const raw = await select({
        message: 'Create a Global/Scoped App?',
        choices: [
            {
                name: 'Scoped',
                value: 'scoped',
                description:
                    'A scope protects application functionality by identifying and restricting access to application files and data. This ensures the application does not disrupt core business services and that other applications cannot interfere with its normal functioning.',
            },
            {
                name: 'Global',
                value: 'global',
                description:
                    'Global scope allows the application to be accessible to other globally scoped applications. They do not offer the same protections as scoped apps. Global applications are eligible for upload to the application repository, but not to the ServiceNow Store.',
            },
        ],
    })
    return raw
}

const scopeNamePrompt = async (defaultScopeName?: string | undefined) => {
    function normalize(value: string) {
        return value.trim()
    }

    const raw = await input({
        message: 'Scope name: ',
        ...(defaultScopeName != null && { default: defaultScopeName }),
        transformer: normalize,
        // intentionally not validating the vendorPrefix here, so that users
        // can optionally override the whole scope (useful for internal/maint devs)
        validate: (value) => ProjectInitValidation.validateScopeName(normalize(value)) ?? true,
    })

    return normalize(raw)
}

const packageNamePrompt: (name: string) => Promise<string> = (generatedName: string) =>
    input({
        message: `NPM package name: `,
        default: generatedName,
        validate(pkgName: string) {
            const error = ProjectInitValidation.validateNpmPackageName(pkgName)
            if (error) {
                return error
            }
            return true
        },
    })

const needPrompt = (context: Arguments, requiredFields: string[]) => {
    return requiredFields.some((field) => !context[field as keyof Arguments])
}

const DEFAULT_VENDOR_PREFIX = 'x_'

interface VendorPrefixResult {
    prefix: string
    fetchedFromInstance: boolean
}

async function getVendorPrefix(credential: LazyCredential | undefined): Promise<VendorPrefixResult> {
    if (!credential) {
        return { prefix: DEFAULT_VENDOR_PREFIX, fetchedFromInstance: false }
    }
    try {
        const prefix = await new Connector(credential).appCreatorVendorPrefix()
        if (!prefix) {
            logger.debug(`Vendor prefix not available from instance. Using default prefix '${DEFAULT_VENDOR_PREFIX}'`)
            return { prefix: DEFAULT_VENDOR_PREFIX, fetchedFromInstance: false }
        }
        return { prefix, fetchedFromInstance: true }
    } catch (error) {
        logger.debug(
            `Could not fetch vendor prefix from instance: ${error}. Using default prefix '${DEFAULT_VENDOR_PREFIX}'`
        )
        return { prefix: DEFAULT_VENDOR_PREFIX, fetchedFromInstance: false }
    }
}

async function warnIfScopePrefixMismatch(
    scopeName: string,
    credential: LazyCredential | undefined,
    cachedResult?: VendorPrefixResult
): Promise<void> {
    if (scopeName === 'global') {
        return
    }

    const { prefix: vendorPrefix, fetchedFromInstance } = cachedResult ?? (await getVendorPrefix(credential))

    // Only validate for x_ prefixes (skip sn_ and other internal prefixes)
    if (fetchedFromInstance && vendorPrefix.startsWith('x_') && !scopeName.startsWith(vendorPrefix)) {
        logger.warn(
            `The scope name '${scopeName}' does not start with your instance's vendor prefix '${vendorPrefix}'. ` +
                `Applications with non-matching prefixes may not install correctly on this instance.`
        )
    }
}

async function promptScopeWithValidation(
    defaultScopeName: string,
    vendorPrefixResult: VendorPrefixResult,
    skipGlobalPrompt = false
): Promise<string> {
    if (!skipGlobalPrompt) {
        const scopeType = await globalPrompt()
        if (scopeType === 'global') {
            return 'global'
        }
    }

    const scopeName = await scopeNamePrompt(defaultScopeName)

    // Only validate if we fetched the prefix from the instance and it starts with x_
    // Skip validation for sn_ and other internal prefixes (internal developers know what they're doing)
    if (!vendorPrefixResult.fetchedFromInstance || !vendorPrefixResult.prefix.startsWith('x_')) {
        return scopeName
    }

    // Check if scope matches vendor prefix and prompt for confirmation if not
    if (!scopeName.startsWith(vendorPrefixResult.prefix)) {
        const warningMessage =
            `The scope name '${scopeName}' does not start with your instance's vendor prefix '${vendorPrefixResult.prefix}'. ` +
            `Applications with non-matching prefixes may not install correctly on this instance.`

        logger.warn(warningMessage)

        // In non-interactive mode (piped input), just warn and continue
        if (!process.stdin.isTTY) {
            return scopeName
        }

        const continueAnyway = await confirm({
            message: 'Do you want to continue with this scope name?',
            default: false,
        })

        if (!continueAnyway) {
            // Recursively prompt again, skipping the global/scoped question
            return promptScopeWithValidation(defaultScopeName, vendorPrefixResult, true)
        }
    }

    return scopeName
}

export async function getPromptAnswers(
    context: Arguments,
    credential: LazyCredential | undefined,
    templates: (TemplateInfo & { id: keyof Templates })[]
): Promise<{ appName: string; packageName: string; scopeName: string; templateId: keyof Templates }> {
    if (
        !needPrompt(context, ['appName', 'packageName', 'scopeName']) &&
        context.template &&
        context.template in templates
    ) {
        // Validate scope prefix even when all args provided via CLI
        await warnIfScopePrefixMismatch(context.scopeName!, credential)

        return { ...context, templateId: context.template } as {
            appName: string
            packageName: string
            scopeName: string
            templateId: keyof Templates
        }
    }

    const hasExistingTemplate = templates.some(({ id }) => id === context.template)
    const templateId = context.template && hasExistingTemplate ? context.template : await templatePrompt(templates)

    const appName = context.appName ?? (await appNamePrompt(context.appName))
    const packageName = context.packageName ?? (await packageNamePrompt(ProjectFactory.createNpmPackageName(appName)))

    // Fetch vendor prefix for default scope suggestion and validation
    const vendorPrefixResult = await getVendorPrefix(credential)

    const defaultScopeName = `${vendorPrefixResult.prefix}${packageName.toLowerCase().replaceAll(/\W/g, '_')}`
        .slice(0, 18)
        .replace(/_$/, '')

    let scopeName: string
    if (context.scopeName) {
        // Scope provided via CLI arg - just warn if mismatch
        scopeName = context.scopeName
        await warnIfScopePrefixMismatch(scopeName, credential, vendorPrefixResult)
    } else {
        // Interactive prompt - allow user to re-enter if mismatch
        scopeName = await promptScopeWithValidation(defaultScopeName, vendorPrefixResult)
    }

    return {
        appName,
        packageName,
        scopeName,
        templateId,
    }
}

export async function getPromptAnswersForInitConvert(context: Arguments) {
    if (!needPrompt(context, ['packageName'])) {
        return { ...context }
    }

    logger.info(`Please provide the missing required fields:`)
    const packageName = await packageNamePrompt('')
    return {
        packageName,
    }
}

export async function getPromptAnswersForInitApply(
    context: Arguments,
    templates: (TemplateInfo & { id: keyof Templates })[]
): Promise<{ templateId: keyof Templates; params: Record<string, string> }> {
    const hasExistingTemplate = templates.some(({ id }) => id === context.template)
    const templateId = context.template && hasExistingTemplate ? context.template : await templatePrompt(templates)
    const template = templates.find(({ id }) => id === templateId)
    const params: Record<string, string> = {}
    if (template?.params) {
        logger.info(`Template "${template.name}" requires additional parameters:`)
        for (const [paramName, param] of Object.entries(template.params)) {
            const answer = await input({
                message: `${param.label}: `,
                default: param.default,
                validate: (value) => (value.trim().length === 0 ? 'Value cannot be empty' : true),
            })
            params[paramName] = answer.trim()
        }
    }

    return { templateId, params }
}
